class Schaf {

   String name;
   String farbe;
   String schnarchGeraeusch;
   String maehGeraeusch;

   Schaf(String name, String farbe, String schnarchGeraeusch, String maehGeraeusch) {
      this.name = name;
      this.farbe = farbe;
      this.schnarchGeraeusch = schnarchGeraeusch;
      this.maehGeraeusch = maehGeraeusch;
   }

   void schlafen() {
      println("Schnarch: " + schnarchGeraeusch);
   }

   void unterhalten() {
      println(maehGeraeusch);
   }

}

class Schaefer {
   String name;

   Schaefer(String name) {
      this.name = name;
   }
}
